<template>
  <div class="zg-container consultation-page">
    <PageHeader title="制度咨询" description="描述业务问题，先核对适用条件，再查看制度依据。"><template #actions><el-button @click="openHistory">我的咨询记录</el-button></template></PageHeader>
    <section class="work-panel query-panel">
      <el-input v-model="qa.question" type="textarea" :rows="3" resize="none" placeholder="例如：境外项目变更款 50 万美元，应该按什么流程办理？" :disabled="qa.loading" @keyup.ctrl.enter="submitQuestion" />
      <div class="query-toolbar">
        <div class="examples"><span>试着问</span><el-button v-for="q in qa.quick" :key="q" text size="small" :disabled="qa.loading" @click="qa.question=q">{{ q }}</el-button></div>
        <div class="query-actions"><el-button v-if="qa.loading" @click="qa.cancel()">停止查询</el-button><el-button v-else @click="newQuestion">新问题</el-button><el-button type="primary" :loading="qa.loading" :disabled="!qa.question.trim()" @click="submitQuestion">{{ qa.historical ? '按当前资料重新核对' : '查询制度' }}</el-button></div>
      </div>
      <div class="query-foot"><span>Ctrl + Enter 提交</span><span v-if="qa.trialMode">本次使用已开启试用记录</span></div>
    </section>
    <div v-if="qa.historical" class="history-notice"><strong>历史咨询 · {{ formatDate(qa.restoredAt) }}</strong><span>{{ qa.answer ? '这是当时的回答和引用；资料与适用条件可能已变化，正式办理前请重新核对。' : '这条咨询尚未形成完整回答。补充条件未保存，请从原问题重新核对。' }}</span></div>
    <div v-if="qa.loading" class="phase-banner" role="status"><el-icon class="is-loading"><Loading /></el-icon>{{ route.query.session && !qa.sessionId ? '正在找回咨询记录…' : phaseText }}</div>
    <DataState v-if="qa.error" :error="qa.error" @retry="retryCurrent" />
    <FollowUpPanel v-if="qa.followUp && !qa.error" :follow_up="qa.followUp" @answered="qa.answerFollowUp" />
    <div v-if="showResult && !qa.error" class="result-layout">
      <section class="work-panel answer-panel">
        <div class="panel-head"><span>咨询结果</span><el-tag :type="resultTone" effect="plain">{{ resultStateText }}</el-tag></div>
        <div v-if="resultNotice" class="result-notice" :class="{ caution: needsReview }">{{ resultNotice }}</div>
        <div class="answer-body" @click="onCiteClick"><div class="markdown-body" v-html="renderedHtml"></div><span v-if="isStreaming" class="stream-caret">▍</span></div>
        <div v-if="qa.answer" class="next-action"><div><strong>{{ qa.relatedCases.length ? '继续处理已关联的事项' : needsReview ? '下一步：补齐事实并由业务人员复核' : '下一步：准备办理事项' }}</strong><p>原问题和咨询记录会关联到事项；金额、组织与其他正式事实请在办理前逐项确认。</p></div><el-button :type="qa.relatedCases.length ? 'default' : 'primary'" :disabled="!!qa.relatedError" @click="startCase">{{ qa.relatedCases.length ? '另建事项' : needsReview ? '发起事项复核' : '准备办理' }}</el-button></div>
        <DataState v-if="qa.relatedError" :error="qa.relatedError" @retry="qa.refreshRelatedCases()" />
        <div v-if="qa.relatedCases.length" class="related-cases"><div v-for="item in qa.relatedCases" :key="item.case_id"><div><strong>{{ item.title }}</strong><small>{{ item.case_no }} · {{ caseStatus(item.status) }}</small></div><el-button type="primary" plain @click="router.push({path:'/case',query:{id:item.case_id}})">{{ ['draft','returned'].includes(item.status) ? '继续处理' : '查看办理记录' }}</el-button></div></div>
        <div v-if="qa.answer" class="feedback-bar"><el-button text :disabled="feedbackDone.includes('favorite') || feedbackLoading" @click="sendFeedback('favorite')">{{ feedbackDone.includes('favorite') ? '已收藏咨询' : '收藏咨询' }}</el-button><span>这份解读是否有帮助？</span><el-button text :disabled="feedbackDone.includes('like') || feedbackLoading" @click="sendFeedback('like')">{{ feedbackDone.includes('like') ? '已记录有帮助' : '有帮助' }}</el-button><el-button text :disabled="feedbackDone.includes('correct')" @click="correctionVisible=true">{{ feedbackDone.includes('correct') ? '已提交纠错' : '指出问题' }}</el-button></div>
      </section>
      <aside class="work-panel sources-panel"><div class="panel-head"><span>制度依据</span><small>{{ qa.citations.length }} 条引用</small></div><div class="sources-body"><div v-for="(c,index) in qa.citations" :key="c.clause_id" :id="'cite-'+c.clause_id" class="cite-anchor"><div class="source-index">依据 {{ index+1 }}</div><SourceCard :citation="c" :active="highlightedId===c.clause_id" @open="openClause" /></div><DataState v-if="!qa.citations.length && !qa.loading" empty empty-title="尚无可用依据" empty-description="该结果不能作为正式办理依据，可补充事实或发起事项复核。" /></div></aside>
    </div>
    <section v-else-if="!qa.loading && !qa.error && !qa.followUp" class="work-panel start-guide"><div class="panel-head">从你要办的事开始</div><div class="guide-body"><p>说明事项、所在组织以及已知的金额和币种。信息不足时，系统会请你补充。</p><p>结果中的引用编号可以定位制度原文；正式办理前需要再次核对事实。</p><el-button plain @click="router.push('/library')">直接查阅制度</el-button></div></section>
    <el-dialog v-model="correctionVisible" title="指出解读中的问题" width="min(600px, 92vw)"><div class="correction-context"><strong>原问题</strong><p>{{ qa.submittedQuestion }}</p></div><el-input v-model="correctionText" type="textarea" :rows="4" placeholder="请说明不准确的结论、引用或缺失条件；如有制度依据也可一并提供。" /><template #footer><el-button @click="correctionVisible=false">取消</el-button><el-button type="primary" :loading="feedbackLoading" :disabled="!correctionText.trim()" @click="submitCorrection">提交纠错</el-button></template></el-dialog>
    <el-drawer v-model="historyVisible" title="我的咨询记录" size="min(760px, 95vw)"><div class="history-toolbar"><el-input v-model="historyKeyword" clearable placeholder="查找曾经咨询的问题" @keyup.enter="searchHistory" /><el-button @click="searchHistory">查找</el-button></div><DataState :error="historyError" :empty="!historyLoading && !historyRows.length" :empty-title="historyKeyword ? '没有找到这类咨询' : '还没有咨询记录'" empty-description="提交过的咨询会保存在这里，便于返回查看依据和继续办理。" @retry="loadHistory"><div v-loading="historyLoading" class="history-list"><button v-for="item in historyRows" :key="item.session_id" class="history-row" @click="restoreHistory(item.session_id)"><div><strong>{{ item.question }}</strong><span>{{ formatDate(item.created_at) }} · {{ !item.completed ? '尚未完成' : item.need_human ? '需业务核对' : '已保存回答' }}<template v-if="item.linked_case_count"> · {{ item.linked_case_count }} 个关联事项</template></span></div><p>{{ item.answer_excerpt || '原问题已保存，补充条件需重新填写。' }}</p><small>查看记录 ›</small></button></div></DataState><el-pagination v-if="historyTotal>historyPageSize" v-model:current-page="historyPage" :page-size="historyPageSize" :total="historyTotal" layout="prev, pager, next" @current-change="loadHistory" /></el-drawer>
  </div>
</template>
<script setup lang="ts">
import { computed, onBeforeUnmount, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { ElMessage } from 'element-plus'
import { Loading } from '@element-plus/icons-vue'
import { marked } from 'marked'
import DOMPurify from 'dompurify'
import { useQaStore } from '@/store/qa'
import * as qaApi from '@/api/qa'
import PageHeader from '@/components/PageHeader.vue'
import DataState from '@/components/DataState.vue'
import SourceCard from '@/components/SourceCard.vue'
import FollowUpPanel from '@/components/FollowUpPanel.vue'
const router=useRouter(); const route=useRoute(); const qa=useQaStore()
const highlightedId=ref<string|null>(null); const correctionVisible=ref(false); const correctionText=ref(''); const feedbackLoading=ref(false); const feedbackDone=ref<string[]>([])
const historyVisible=ref(false);const historyLoading=ref(false);const historyError=ref('');const historyKeyword=ref('');const historyRows=ref<qaApi.QASessionSummary[]>([]);const historyTotal=ref(0);const historyPage=ref(1);const historyPageSize=20;let historyVersion=0
const isStreaming=computed(()=>qa.phase==='generating' && !qa.answer)
const showResult=computed(()=>!!qa.streamingText || !!qa.answer || qa.citations.length>0)
const needsReview=computed(()=>qa.needHuman || qa.insufficient || !qa.authorityVerified || !qa.groundingPassed)
const phaseText=computed(()=>qa.phase==='generating' ? '正在整理制度解读…' : '正在查找相关条款…')
const resultStateText=computed(()=>qa.historical ? '历史回答' : qa.loading ? '正在生成' : qa.degradedReason ? '服务暂不可用' : qa.insufficient ? '制度未覆盖' : qa.needHuman ? '需业务复核' : !qa.authorityVerified ? '来源待确认' : !qa.groundingPassed ? '引用待复核' : '来源已确认')
const resultTone=computed<'success'|'warning'|'info'>(()=>qa.loading ? 'info' : needsReview.value ? 'warning' : 'success')
const resultNotice=computed(()=>{ if(qa.loading || qa.historical) return ''; if(qa.degradedReason) return '检索服务暂不可用，本次没有形成制度结论。请稍后重试。'; const notices=[qa.contradiction && qa.contraDetail ? `制度口径需核对：${qa.contraDetail}` : '',...qa.qualityWarnings].filter(Boolean); if(notices.length) return notices.join('；'); return needsReview.value ? '当前资料或条件尚不足以形成正式办理结论。请核对依据，并提交事项供业务人员复核。' : '解读所引用的资料来源已确认。请结合原文与实际业务事实核对适用范围。' })
function renderMarkdown(md:string):string { if(!md) return ''; const dirty=marked.parse(md.replace(/\[(\d{1,2})\]/g,'@@ZG_CITE_$1@@'),{breaks:true,gfm:true}) as string; const html=DOMPurify.sanitize(dirty,{USE_PROFILES:{html:true},FORBID_TAGS:['style','iframe','form','input','object','embed'],FORBID_ATTR:['style']}); return html.replace(/@@ZG_CITE_(\d{1,2})@@/g,(_m:string,n:string)=>`<button type="button" class="cite-badge" data-cite="${n}" title="查看第 ${n} 条依据">${n}</button>`) }
const renderedHtml=computed(()=>renderMarkdown(qa.streamingText || qa.answer?.answer_interpret || ''))
function onCiteClick(event:MouseEvent) { const badge=(event.target as Element|null)?.closest('.cite-badge') as HTMLElement|null; const citation=qa.citations[Number(badge?.dataset.cite || '0')-1]; if(!citation) return; highlightedId.value=citation.clause_id; document.getElementById('cite-'+citation.clause_id)?.scrollIntoView({behavior:'smooth',block:'center'}) }
function openClause(id:string) { qa.recordCitationOpen(id); router.push({path:`/clause/${id}`,query:{from:'qa',session_id:qa.sessionId || undefined}}) }
function startCase() { router.push({path:'/case',query:{new:'1',question:qa.submittedQuestion,session:qa.sessionId || ''}}) }
function formatDate(value:string|null){return value ? value.slice(0,16).replace('T',' ') : '时间未记录'}
function caseStatus(value:string){return ({draft:'草稿',returned:'已退回补充',review_required:'待人工复核',assessed:'已生成指南',confirmed:'已人工确认'} as Record<string,string>)[value] || value}
async function loadHistory(){const version=++historyVersion;historyLoading.value=true;historyError.value='';try{const result=await qaApi.mySessions({keyword:historyKeyword.value.trim(),offset:(historyPage.value-1)*historyPageSize,limit:historyPageSize});if(version===historyVersion){historyRows.value=result.items;historyTotal.value=result.total}}catch(error:any){if(version===historyVersion)historyError.value=error?.response?.data?.message || '咨询记录暂时无法读取，请稍后重试。'}finally{if(version===historyVersion)historyLoading.value=false}}
function openHistory(){historyVisible.value=true;void loadHistory()}
function searchHistory(){historyPage.value=1;void loadHistory()}
function restoreHistory(id:string){historyVisible.value=false;router.push({path:'/qa',query:{session:id}})}
function newQuestion(){qa.clear();router.replace('/qa')}
async function submitQuestion(){if(qa.loading || !qa.question.trim())return;await router.replace('/qa');await qa.ask()}
function retryCurrent(){if(typeof route.query.session==='string' && !qa.sessionId)void qa.restoreSession(route.query.session);else void qa.retry()}
async function sendFeedback(type:string,content?:string) { if(!qa.answer) return; feedbackLoading.value=true; try { await qa.feedback(type,content); feedbackDone.value.push(type); ElMessage.success(type==='correct' ? '已提交审核中心' : type==='favorite' ? '咨询已收藏' : '已记录'); return true } catch { return false } finally { feedbackLoading.value=false } }
async function submitCorrection() { if(!correctionText.value.trim()) return; if(await sendFeedback('correct',correctionText.value.trim())) { correctionVisible.value=false; correctionText.value='' } }
watch(()=>qa.sessionId,()=>{feedbackDone.value=[];correctionText.value='';correctionVisible.value=false})
watch(()=>qa.recordedFeedback,(types)=>{feedbackDone.value=[...types]},{deep:true})
watch(()=>[route.query.session,route.query.q,route.query.ask],([session,value,autoAsk])=>{if(typeof session==='string' && session){if(qa.sessionId!==session || (!qa.answer && !qa.historical))void qa.restoreSession(session);else void qa.refreshRelatedCases();return}if(typeof value==='string' && value.trim()){if(qa.question===value && (qa.answer || qa.followUp || qa.loading))return;qa.clear();qa.question=value;if(autoAsk==='1')void qa.ask()}},{immediate:true})
onBeforeUnmount(()=>{++historyVersion;if(qa.loading) qa.cancel()})
</script>
<style scoped>
.history-notice{display:flex;flex-direction:column;gap:6px;padding:12px 16px;border:1px solid var(--zg-border);background:var(--zg-panel-soft);font-size:12px;line-height:1.7;color:var(--zg-text-secondary)}.history-notice strong{color:var(--zg-text)}.history-toolbar{display:flex;gap:10px;margin-bottom:16px}.history-list{display:flex;flex-direction:column;gap:10px;min-height:80px}.history-row{display:block;text-align:left;width:100%;padding:14px;border:1px solid var(--zg-border);background:var(--zg-card);color:var(--zg-text);cursor:pointer;font:inherit}.history-row:hover{border-color:var(--zg-primary);background:var(--zg-panel-soft)}.history-row strong{display:block;line-height:1.6}.history-row span,.history-row p{color:var(--zg-text-secondary);font-size:12px;line-height:1.7}.history-row span{display:block;margin-top:5px}.history-row p{margin:8px 0}.history-row small{color:var(--zg-primary)}.related-cases{border-top:1px solid var(--zg-border);padding:0 16px}.related-cases>div{display:flex;justify-content:space-between;align-items:center;gap:14px;padding:12px 0;border-bottom:1px solid var(--zg-border-light)}.related-cases strong,.related-cases small{display:block;font-size:12px;line-height:1.7}.related-cases small{color:var(--zg-text-secondary)}
.consultation-page{display:flex;flex-direction:column;gap:14px}.query-panel{padding:16px}.query-toolbar{display:flex;justify-content:space-between;align-items:flex-start;gap:14px;margin-top:10px}.examples{display:flex;align-items:center;flex-wrap:wrap;gap:0 6px;color:var(--zg-text-weak);font-size:12px}.examples .el-button{margin:0}.query-actions{display:flex;flex-shrink:0;gap:8px}.query-actions .el-button{margin:0}.query-foot{display:flex;justify-content:space-between;margin-top:8px;color:var(--zg-text-weak);font-size:11px}.phase-banner{display:flex;align-items:center;gap:8px;color:var(--zg-primary);padding:10px 12px;background:var(--zg-primary-soft);border:1px solid var(--zg-border)}.result-layout{display:grid;grid-template-columns:minmax(0,1fr) 350px;gap:14px;align-items:start}.panel-head{display:flex;justify-content:space-between;align-items:center}.panel-head small{color:var(--zg-text-weak);font-weight:400}.result-notice{padding:11px 16px;border-bottom:1px solid var(--zg-border-light);color:#397553;font-size:12px;line-height:1.65}.result-notice.caution{background:#fffaf0;color:#80500a}.answer-body{padding:18px 20px;min-height:120px}.sources-body{padding:12px}.source-index{color:var(--zg-text-weak);font-size:11px;margin-bottom:5px}.cite-anchor{scroll-margin-top:12px;margin-bottom:12px}.next-action{display:flex;align-items:center;justify-content:space-between;gap:14px;padding:14px 16px;border-top:1px solid var(--zg-border);background:var(--zg-panel-soft)}.next-action strong{font-size:13px}.next-action p{margin:5px 0 0;color:var(--zg-text-secondary);font-size:12px;line-height:1.5}.feedback-bar{display:flex;align-items:center;padding:8px 16px;border-top:1px solid var(--zg-border-light);font-size:12px;color:var(--zg-text-secondary)}.guide-body{padding:16px}.guide-body p{margin:0 0 10px;color:var(--zg-text-secondary);line-height:1.7}.correction-context{padding:12px;margin-bottom:12px;background:var(--zg-panel-soft);line-height:1.7}.correction-context p{margin:4px 0 0}.markdown-body{line-height:1.8;word-break:break-word}.markdown-body :deep(p){margin:5px 0 12px}.markdown-body :deep(h1),.markdown-body :deep(h2),.markdown-body :deep(h3){font-size:16px;margin:18px 0 9px}.markdown-body :deep(ul),.markdown-body :deep(ol){padding-left:24px}.markdown-body :deep(blockquote){margin:12px 0;padding:7px 12px;border-left:3px solid var(--zg-primary);background:var(--zg-primary-soft)}.markdown-body :deep(table){width:100%;border-collapse:collapse}.markdown-body :deep(th),.markdown-body :deep(td){padding:8px;border:1px solid var(--zg-border)}.markdown-body :deep(pre){padding:12px;background:var(--zg-panel-soft);overflow:auto}.markdown-body :deep(.cite-badge){border:1px solid var(--zg-primary);color:var(--zg-primary);background:var(--zg-primary-soft);font-size:11px;cursor:pointer;padding:0 5px;margin:0 3px}.stream-caret{color:var(--zg-primary)}@media(max-width:1200px){.result-layout{grid-template-columns:minmax(0,1fr) 310px}}@media(max-width:900px){.result-layout{grid-template-columns:1fr}.query-toolbar{flex-direction:column}.query-actions{align-self:flex-end}.next-action{align-items:flex-start;flex-direction:column}}
</style>
